/**
 * Sample faces for gallery films (128px JPEG data URLs). Use these for people in scenes —
 * never real users, never initials-only avatars when a face fits the story.
 *   import { faces, face } from '/__papr__/papr-faces.ts';
 *   face("priya") -> data URL;  faces -> { name: url }
 */
export const faces: Record<string, string> = {
  aisha: "data:image/jpeg;base64,",
  dana: "data:image/jpeg;base64,",
  james: "data:image/jpeg;base64,",
  lena: "data:image/jpeg;base64,",
  marcus: "data:image/jpeg;base64,",
  mei: "data:image/jpeg;base64,",
  omar: "data:image/jpeg;base64,",
  priya: "data:image/jpeg;base64,",
  raj: "data:image/jpeg;base64,",
  sofia: "data:image/jpeg;base64,",
  theo: "data:image/jpeg;base64,",
};

/** A face by name (falls back to the first face). */
export const face = (name: string): string => faces[name] ?? Object.values(faces)[0]!;

/** All faces, in a stable order (for grids of people). */
export const faceList = (): string[] => Object.values(faces);
